//★Wcraft guide★ include부분 주석처리 -> include("../js/protected_dep_cal.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
scwin.vScrenID = "ULDSTF40209.xml";
scwin.notiId;
scwin.vSecugrpID = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_read = function() {
    var url = "/ProtectedDepositionManagement.do?method=readProtectedDeposition&inputMessageId=PROTECTED_DEPOSITION_FEE_READ_INOUT&outputMessageId=PROTECTED_DEPOSITION_FEE_READ_INOUT";
    url += "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&notiId=" + scwin.notiId;
    dts_readPrtdepo.DataID = encodeURI(url);
    dts_readPrtdepo.reset();

    //alert("ACT_YN ----> "+dts_readPrtdepo.NameString(1, "ACT_YN"));

};
scwin.fn_update = function() {
    // validation check//

    if (txb_isur_cd.getValue() == "" && txb_com_nm.getValue() == "") {
        $c.win.alert("[등록할 법인]을 선택해주세요.");
        txb_isur_cd.focus();
        return;
    }
    /*
    		if(med_RsnOccrDdtm.Text == ""){
    			alert( getMessageParam("MSG-A005", "사유발생일") );
    			med_RsnOccrDdtm.Focus();
    			return ;
    		}
    */
    med_RsnOccrDdtm.setValue("");
    if (txb_nm.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "성명"));
        txb_nm.focus();
        return;
    }

    /*생년월일은 필수사항 아님
    		if(txb_RESDBZ_REG_NO.value == ""){
    			alert( getMessageParam("MSG-A005", "생년월일(사업자번호)") );
    			txb_RESDBZ_REG_NO.focus();
    			return ;
    		}
    */
    if (med_PrtdepoShrs.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "의무보유대상주식"));
        med_PrtdepoShrs.focus();
        return;
    }
    if (cmb_PrtdepoPrnTpCd.BindColVal == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "대상자구분"));
        cmb_PrtdepoPrnTpCd.focus();
        return;
    }
    if (cmb_PrtdepoObjKindCd.BindColVal == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "의무보유대상종류"));
        cmb_PrtdepoObjKindCd.focus();
        return;
    }
    if (cmb_PrtdepoRsnCd.BindColVal == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "의무보유사유"));
        cmb_PrtdepoRsnCd.focus();
        return;
    }

    //2009.04.20 보호예수 사유가 해당사항없음이면 기간입력을 하지 않는다.
    if (cmb_PrtdepoRsnCd.BindColVal == "70") {
        if (med_PrtdepoStrtDd.getValue() != "" || med_PrtdepoEndDd.getValue() != "") {
            $c.win.alert("의무보유사유가 [해당사항없음] 일때는 의무보유기간을 입력하지 않습니다.");
            med_PrtdepoStrtDd.focus();
            return;
        }
    } else {
        if (med_PrtdepoStrtDd.getValue() == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "의무보유시작일"));
            med_PrtdepoStrtDd.focus();
            return;
        }
        if (med_PrtdepoEndDd.getValue() == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "의무보유종료일"));
            med_PrtdepoEndDd.focus();
            return;
        }
    }

    /*
    		if(cmb_MiscPrtdepoRsnCd.BindColVal == ''){
    			alert("기타보호예수사유코드를 입력하세요");
    			cmb_MiscPrtdepoRsnCd.Focus();
    			return;
    		}

    		//2009.04.20 기타보호예수 사유가 해당사항없음이면 기간입력을 하지 않는다.
    		if(cmb_MiscPrtdepoRsnCd.BindColVal == '04'){
    			if(med_MiscPrtdepoStrtDd.Text != "" || med_MiscPrtdepoEndDd.Text != ""){
    				alert("기타보호예수사유가 [해당사항없음] 일때는 기타보호예수기간을 입력하지 않습니다.");
    				med_MiscPrtdepoStrtDd.Focus();
    				return;
    			}
    		}else{
    			if(med_MiscPrtdepoStrtDd.Text == ""){
    				alert( getMessageParam("MSG-A005", "기타보호예수시작일") );
    				med_MiscPrtdepoStrtDd.Focus();
    				return ;
    			}
    			if(med_MiscPrtdepoEndDd.Text == ""){
    				alert( getMessageParam("MSG-A005", "기타보호예수종료일") );
    				med_MiscPrtdepoEndDd.Focus();
    				return ;
    			}
    		}
    */

    if (scwin.dateCheck() == false) {
        return;
    }
    if (scwin.dateCheckMisc() == false) {
        return;
    }


    /* 20081015 조치여부 DB저장 */
    var act_yn_flag = "";
    if (chk_ActYn.checked) {
        //조치여부에 체크표시를 하면 '1' 예로 들어감..
        act_yn_flag = "1";
    } else {
        act_yn_flag = "2";
    }
    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "PRTDEPO_PRN_TP_CD", cmb_PrtdepoPrnTpCd.BindColVal);
    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "PRTDEPO_OBJ_KIND_CD", cmb_PrtdepoObjKindCd.BindColVal);
    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "PRTDEPO_OBJ_TP_CD", cmb_PrtdepoObjTpCd.BindColVal);
    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "PRTDEPO_RSN_CD", cmb_PrtdepoRsnCd.BindColVal);
    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "PRTDEPO_RSN_MNGRGHT_TP_CD", cmb_PrtdepoRsnMngrghtTpCd.BindColVal);
    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "PRTDEPO_RSN_FNC_TP_CD", cmb_PrtdepoRsnFncTpCd.BindColVal);
    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "ACT_YN", act_yn_flag);
    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "PRTDEPO_RSN_REMK", txb_PrtdepoRsnRemk.getValue()); //2008-12-01 보호예수사유비고
    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "MISC_PRTDEPO_RSN_CD", cmb_MiscPrtdepoRsnCd.BindColVal); //2008-12-01 기타보호예수사유코드
    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "MISC_PRTDEPO_RSN_REMK", txb_MiscPrtdepoRsnRemk.getValue()); //2008-12-01 기타보호예수사유비고

    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "MISC_PRTDEPO_STRT_DD", med_MiscPrtdepoStrtDd.getValue()); //2008-12-01 기타보호예수개시일자
    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "MISC_PRTDEPO_END_DD", med_MiscPrtdepoEndDd.getValue()); //2008-12-01 기타보호예수종료일자

    //alert(dts_readPrtdepo.Text); //데이타셋내용확인

    var rtn = confirm('내용을 수정 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        trs_Update.Action = "/ProtectedDepositionManagement.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&method=modifyProtectedDeposition&notiId=" + scwin.notiId;
        trs_Update.KeyValue = "JSP(I:pInput=dts_readPrtdepo)";
        trs_Update.Post();
    }
};
scwin.fn_save = function() {
    // validation check//
    if (txb_isur_cd.getValue() == "" && txb_com_nm.getValue() == "") {
        $c.win.alert("[등록할 법인]을 선택해주세요.");
        txb_isur_cd.focus();
        return;
    }
    /*
    		if(med_RsnOccrDdtm.Text == ""){
    			alert( getMessageParam("MSG-A005", "사유발생일") );
    			med_RsnOccrDdtm.Focus();
    			return ;
    		}
    */
    med_RsnOccrDdtm.setValue("");
    if (txb_nm.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "성명"));
        txb_nm.focus();
        return;
    }

    /*생년월일은 필수사항 아님
    		if(txb_RESDBZ_REG_NO.value == ""){
    			alert( getMessageParam("MSG-A005", "생년월일(사업자번호)") );
    			txb_RESDBZ_REG_NO.focus();
    			return ;
    		}
    */
    if (med_PrtdepoShrs.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "의무보유대상주식"));
        med_PrtdepoShrs.focus();
        return;
    }
    if (cmb_PrtdepoPrnTpCd.BindColVal == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "대상자구분"));
        cmb_PrtdepoPrnTpCd.focus();
        return;
    }
    if (cmb_PrtdepoObjKindCd.BindColVal == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "의무보유대상종류"));
        cmb_PrtdepoObjKindCd.focus();
        return;
    }
    /*
    if(cmb_PrtdepoRsnCd.BindColVal == ""){
    	alert( getMessageParam("MSG-A005", "보호예수사유") );
    	cmb_PrtdepoRsnCd.Focus();
    	return ;
    }
    */
    if (med_PrtdepoStrtDd.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "의무보유시작일"));
        med_PrtdepoStrtDd.focus();
        return;
    }
    if (med_PrtdepoEndDd.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "의무보유종료일"));
        med_PrtdepoEndDd.focus();
        return;
    }

    /*
    		if(med_MiscPrtdepoStrtDd.Text == ""){
    			alert( getMessageParam("MSG-A005", "기타보호예수시작일") );
    			med_MiscPrtdepoStrtDd.Focus();
    			return ;
    		}
    		if(med_MiscPrtdepoEndDd.Text == ""){
    			alert( getMessageParam("MSG-A005", "기타보호예수종료일") );
    			med_MiscPrtdepoEndDd.Focus();
    			return ;
    		}
    */

    if (scwin.dateCheck() == false) {
        return;
    }
    if (scwin.dateCheckMisc() == false) {
        return;
    }
    dts_savePrtdepo.setCellData(dts_savePrtdepo.getRowPosition(), "PRTDEPO_PRN_TP_CD", cmb_PrtdepoPrnTpCd.BindColVal);
    dts_savePrtdepo.setCellData(dts_savePrtdepo.getRowPosition(), "PRTDEPO_OBJ_KIND_CD", cmb_PrtdepoObjKindCd.BindColVal);
    dts_savePrtdepo.setCellData(dts_savePrtdepo.getRowPosition(), "PRTDEPO_OBJ_TP_CD", cmb_PrtdepoObjTpCd.BindColVal);
    dts_savePrtdepo.setCellData(dts_savePrtdepo.getRowPosition(), "PRTDEPO_RSN_CD", cmb_PrtdepoRsnCd.BindColVal);
    dts_savePrtdepo.setCellData(dts_savePrtdepo.getRowPosition(), "PRTDEPO_RSN_MNGRGHT_TP_CD", cmb_PrtdepoRsnMngrghtTpCd.BindColVal);
    dts_savePrtdepo.setCellData(dts_savePrtdepo.getRowPosition(), "PRTDEPO_RSN_FNC_TP_CD", cmb_PrtdepoRsnFncTpCd.BindColVal);
    dts_savePrtdepo.setCellData(dts_savePrtdepo.getRowPosition(), "PRTDEPO_RSN_REMK", txb_PrtdepoRsnRemk.getValue()); //2008-12-01 보호예수사유비고
    dts_savePrtdepo.setCellData(dts_savePrtdepo.getRowPosition(), "MISC_PRTDEPO_RSN_CD", cmb_MiscPrtdepoRsnCd.BindColVal); //2008-12-01 기타보호예수사유코드
    dts_savePrtdepo.setCellData(dts_savePrtdepo.getRowPosition(), "MISC_PRTDEPO_RSN_REMK", txb_MiscPrtdepoRsnRemk.getValue()); //2008-12-01 기타보호예수사유비고

    dts_savePrtdepo.setCellData(dts_savePrtdepo.getRowPosition(), "MISC_PRTDEPO_STRT_DD", med_MiscPrtdepoStrtDd.getValue()); //2008-12-01 기타보호예수개시일자
    dts_savePrtdepo.setCellData(dts_savePrtdepo.getRowPosition(), "MISC_PRTDEPO_END_DD", med_MiscPrtdepoEndDd.getValue()); //2008-12-01 기타보호예수종료일자


    var rtn = confirm('내용을 등록 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        trs_Save.Action = "/ProtectedDepositionManagement.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=createProtectedDeposition";
        trs_Save.KeyValue = "JSP(I:pInput=dts_savePrtdepo)";
        trs_Save.Post();
    }
};
scwin.fn_delete = function() {
    var rtn = confirm('내용을 삭제 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {

        //dts_deletePrtdepo.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_deletePrtdepo.insertRow();
        dts_deletePrtdepo.setCellData(1, "PRTDEPO_ID", scwin.notiId);
        trs_Delete.Action = "/ProtectedDepositionManagement.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04 + "&method=removeProtectedDeposition";
        trs_Delete.KeyValue = "JSP(I:pInput=dts_deletePrtdepo)";
        trs_Delete.Post();
    }
};
scwin.fn_GetPar = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.vSecugrpID; // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetPar = function(arrPar) {
    txb_isur_cd.setValue(arrPar[0].ISUR_CD);
    txb_com_nm.setValue(arrPar[0].COM_NM);
};
scwin.dateCheck = function() {
    if (parseInt(med_PrtdepoStrtDd.getValue(), '10') > parseInt(med_PrtdepoEndDd.getValue(), '10')) {
        $c.win.alert("[의무보유기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        med_PrtdepoStrtDd.setValue("");
        med_PrtdepoEndDd.setValue("");
        return false;
    }
};
scwin.dateCheckMisc = function() {
    if (parseInt(med_MiscPrtdepoStrtDd.getValue(), '10') > parseInt(med_MiscPrtdepoEndDd.getValue(), '10')) {
        $c.win.alert("[기타의무보유기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        med_MiscPrtdepoStrtDd.setValue("");
        med_MiscPrtdepoEndDd.setValue("");
        return false;
    }
};
scwin.fn_Search_Popup_onclick = function() {
    $c.lc.fn_PopFindCorpChrg(scwin.vSecugrpID);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "의무보유등록"));
    //self.close();
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "의무보유등록"));
    $c.win.alert(trs_Save.ErrorMsg);
    //alert(dts_C_All.ErrorMsg);

};
scwin.trs_Update_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "의무보유수정"));
    self.close();
};
scwin.trs_Update_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "의무보유수정"));
    $c.win.alert(trs_Update.ErrorMsg);
    //alert(dts_C_All.ErrorMsg);

};
scwin.trs_Delete_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "의무보유삭제"));
    self.close();
};
scwin.trs_Delete_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "의무보유삭제"));
    $c.win.alert(trs_Delete.ErrorMsg);
    //alert(dts_C_All.ErrorMsg);

};
