scwin.btn_SCal_onclick = function() {
    popUpCalendar(med_PrtdepoStrtDd, 'med_PrtdepoStrtDd', 'yyyymmdd');
};
scwin.btn_ECal_onclick = function() {
    popUpCalendar(med_PrtdepoEndDd, 'med_PrtdepoEndDd', 'yyyymmdd');
};
